const sha = (value) => createHash('sha256').update(value).digest('hex');

async function fixture(t, state) {
  const root = await mkdtemp(join(tmpdir(), 'sol-legacy-record-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  const store = await createObservationStore(root); store.workspaceId = legacy.workspaceId;
  for (const [path, bytes] of Object.entries(legacy[state].files)) {
    await mkdir(dirname(join(root, path)), { recursive: true });
    await writeFile(join(root, path), Buffer.from(bytes, 'base64'));
  }
  for (const entry of legacy.archives) {
    const directory = join(store.observationsRoot, entry.handle); await mkdir(directory);
    for (const [path, bytes] of Object.entries(entry.files)) await writeFile(join(directory, path), Buffer.from(bytes, 'base64'));
  }
  const records = new ArchiveRecords(store);
  const original = await records.stored(legacy[state].ref, 'sol_change_record', 'change_record');
  const rules = JSON.parse(await readFile(join(root, 'rules.json'), 'utf8'));
  const changes = new ChangeCoordinator({ store, records, loadConfig: (signal) => readContextConfiguration(root, 'context.json', { signal }) }, rules);
  let runners = 0;
  changes.validator.revalidate = async () => { runners++; throw new Error('Migration must not run checks.'); };
  changes.validator.freshness = async () => { runners++; throw new Error('Legacy completion has no current policy qualification.'); };
  await mkdir(dirname(changes.pointer), { recursive: true });
  await writeAtomicJSON(changes.pointer, { schema_version: 1, workspace_id: store.workspaceId,
    change: { id: original.id, version: original.version }, record: legacy[state].ref });
  return { root, store, records, changes, original, runners: () => runners };
}

for (const state of ['completed', 'pending']) test(`frozen legacy ${state} stays immutable, projects stale with zero writes and migrates only on explicit status`, async (t) => {
  const f = await fixture(t, state);
  const originalPath = join(f.store.observationsRoot, legacy[state].ref.handle, 'raw');
  const originalBytes = await readFile(originalPath); const active = await readFile(f.changes.pointer);
  assert.equal(sha(originalBytes), legacy[state].ref.sha256);
  assert.equal(f.original.observed.fingerprint_kind, undefined);
  assert.equal(f.original.observed.items.find((item) => item.type === 'file').mode, undefined);
  const { version, ...body } = f.original;
  assert.equal(sha(JSON.stringify(body)), version);
  const archives = await readdir(f.store.observationsRoot);
  const projection = (await f.changes.inspectLocked({ targets: ['src/html.mjs'] })).projection;
  assert.equal(projection.task_complete, false); assert.equal(projection.needs_status_refresh, true);
  assert.equal(projection.state, state === 'pending' ? 'interrupted' : 'dirty');
  if (state === 'completed') { assert.equal(projection.review.validity, 'stale'); assert.equal(projection.completion.validity, 'stale'); }
  assert.deepEqual(await readFile(f.changes.pointer), active);
  assert.deepEqual(await readdir(f.store.observationsRoot), archives); assert.equal(f.runners(), 0);
  const archive = f.records.archive.bind(f.records);
  f.records.archive = async () => { throw new Error('Migration archive unavailable.'); };
  await assert.rejects(f.changes.status(), /Migration archive unavailable/);
  assert.deepEqual(await readFile(f.changes.pointer), active);
  f.records.archive = archive;
  const migrated = await f.changes.status(); const current = await f.changes.read();
  assert.equal(current.record.previous_handle, legacy[state].ref.handle);
  assert.equal(current.record.input_fingerprint_kind, INPUT_FINGERPRINT_KIND);
  assert.equal(current.record.observed.fingerprint_kind, INPUT_FINGERPRINT_KIND);
  assert.equal(current.record.latest_validation, null); assert.equal(current.record.review_ref, null); assert.equal(current.record.completion_ref, null);
  assert.deepEqual(await readFile(originalPath), originalBytes);
  assert.deepEqual(await f.records.stored(legacy[state].ref, 'sol_change_record', 'change_record'), f.original);
  const history = await f.changes.validationHistory(current);
  assert.ok(history.length > 0, 'Original history remains readable across the format boundary.');
  if (state === 'completed') {
    assert.equal(migrated.accumulated_path_count, f.original.accumulated_paths.length, 'Format migration must not invent changed paths.');
    assert.equal(current.record.pending, null);
  } else {
    assert.equal(current.record.recovery.status, 'unknown');
    assert.equal(current.record.pending.operation_id, f.original.pending.operation_id);
    assert.equal(current.record.recovery.outcome_ref, null);
    assert.equal(current.record.pending.starting_binding, undefined);
    const again = await f.changes.status(); assert.equal(again.change.version, migrated.change.version);
    const resumed = await f.changes.transition(again.change, 'dirty');
    assert.equal(resumed.state, 'dirty'); assert.equal((await f.changes.read()).record.pending, null);
  }
  assert.equal(f.runners(), 0);
});

test('unknown fingerprint formats and changed historical bodies fail closed without replacing active identity', async (t) => {
  const f = await fixture(t, 'completed'); const active = await readFile(f.changes.pointer);
  for (const mode of ['unknown_format', 'original_hash']) {
    let value = structuredClone(f.original);
    if (mode === 'unknown_format') {
      value.observed.fingerprint_kind = 'unrecognized_future_policy';
      const { version, ...body } = value; value.version = sha(JSON.stringify(body));
    } else value.task.goal = 'Changed without updating the original historical hash.';
    const raw = await f.records.archive(value, 'sol_change_record');
    await writeAtomicJSON(f.changes.pointer, { schema_version: 1, workspace_id: f.store.workspaceId,
      change: { id: value.id, version: value.version }, record: raw });
    const before = await readFile(f.changes.pointer);
    await assert.rejects(f.changes.status(), { code: 'CHANGE_CORRUPT' });
    await assert.rejects(f.changes.inspectLocked(), { code: 'CHANGE_CORRUPT' });
    assert.deepEqual(await readFile(f.changes.pointer), before); assert.equal(f.runners(), 0);
    await writeFile(f.changes.pointer, active);
  }
});
